"""Calculate salaries for the cleaning service's monthly billing periods."""

import csv
import json
import re
from collections import defaultdict
from datetime import date, timedelta
from decimal import Decimal, ROUND_HALF_UP


EMPLOYEES = "/app/dataset/employees.csv"
TASKS = "/app/dataset/tasks.csv"
TIMESHEET = "/app/dataset/timesheet.csv"


def _first_weekday_of_month(day: date, weekday: int) -> date:
    first = day.replace(day=1)
    return first + timedelta(days=(weekday - first.weekday()) % 7)


def _billing_month(day: date, weekday: int) -> date:
    start = _first_weekday_of_month(day, weekday)
    if day < start:
        previous_month = day.replace(day=1) - timedelta(days=1)
        start = _first_weekday_of_month(previous_month, weekday)
    return start


def answer() -> dict[str, list[int]]:
    with open(EMPLOYEES, newline="", encoding="utf-8") as file:
        rates = {
            row["PESEL"]: Decimal(row["hourly_rate"])
            for row in csv.DictReader(file)
        }

    with open(TASKS, newline="", encoding="utf-8") as file:
        task_pay = {
            int(row["task_id"]): Decimal(row["pay_per_completion"])
            for row in csv.DictReader(file)
        }

    valid_rows = []
    seen = set()
    with open(TIMESHEET, newline="", encoding="utf-8") as file:
        for row in csv.DictReader(file):
            employee = row["employee_id"]
            if employee not in rates:
                continue
            try:
                work_date = date.fromisoformat(row["date"])
                hours = Decimal(row["hours_worked"])
            except (ValueError, TypeError):
                continue
            if hours < 0 or hours > 24:
                continue

            # The row ID is different on otherwise identical duplicate entries.
            contents = tuple((key, value) for key, value in row.items() if key != "id")
            if contents in seen:
                continue
            seen.add(contents)
            valid_rows.append((row, work_date, hours))

    if not valid_rows:
        return {}

    weekday = min(work_date for _, work_date, _ in valid_rows).weekday()
    totals = defaultdict(Decimal)
    months = set()
    for row, work_date, hours in valid_rows:
        month = _billing_month(work_date, weekday)
        months.add(month)
        earned_bonus = sum(
            (task_pay.get(int(task_id), Decimal(0))
             for task_id in re.findall(r"\d+", row["performed_tasks"])),
            Decimal(0),
        )
        totals[(row["employee_id"], month)] += hours * rates[row["employee_id"]] + earned_bonus

    ordered_months = sorted(months)
    return {
        employee: [
            int(totals[(employee, month)].quantize(Decimal("1"), rounding=ROUND_HALF_UP))
            for month in ordered_months
        ]
        for employee in rates
    }


if __name__ == "__main__":
    with open("/app/answer.json", "w", encoding="utf-8") as file:
        json.dump(answer(), file, default=list)

